while (true) {
  const res: any = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const items = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!items.length) break;
  issues.push(...items);
  if (items.length < 50) break;
  page++;
}
const counts: Record<string, Set<number>> = {};
