  const num = issue.number;
  const cres: any = await tools.list_comments({ repo: "acme/web", number: num });
  let comments = Array.isArray(cres) ? cres : (cres?.items ?? cres?.comments ?? []);
  let cp = 2;
  while (comments.length === 50) {
    const more: any = await tools.list_comments({ repo: "acme/web", number: num, page: cp });
    const mi = Array.isArray(more) ? more : (more?.items ?? more?.comments ?? []);
    if (!mi.length) break;
    comments = comments.concat(mi);
    if (mi.length < 50) break;
    cp++;
  }
  for (const c of comments) {
    const login = c?.user?.login ?? c?.author?.login ?? c?.author ?? c?.user;
    if (!login || typeof login !== "string") continue;
    (counts[login] ??= new Set()).add(num);
  }
}
const result = Object.entries(counts)
  .filter(([, s]) => s.size >= 4)
  .map(([login, s]) => ({ login, issues: [...s] }));
return { issueCount: issues.length, sample: issues.slice(0, 1), result };
